#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

int main() {
    // 1. Minmax element across a range
    std::vector<int> data = {14, 5, 23, 5, 88, 42, 88, 19};
    auto [minIt, maxIt] = std::minmax_element(data.begin(), data.end());
    std::cout << "Min: " << *minIt << " Max: " << *maxIt << "\n";

    // 2. Sorting and unique (Erase-Remove / Unique Idiom)
    std::sort(data.begin(), data.end());
    auto newEnd = std::unique(data.begin(), data.end());
    data.erase(newEnd, data.end());

    std::cout << "Unique sorted data:";
    for (int n : data) {
        std::cout << " " << n;
    }
    std::cout << "\n";

    // 3. Set operations on sorted ranges
    std::vector<int> setA = {5, 14, 19, 23, 42, 88};
    std::vector<int> setB = {10, 14, 20, 23, 90};
    std::vector<int> diff;

    // Elements in setA not in setB
    std::set_difference(setA.begin(), setA.end(),
                        setB.begin(), setB.end(),
                        std::back_inserter(diff));

    std::cout << "Difference (setA - setB):";
    for (int n : diff) {
        std::cout << " " << n;
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> nums = {30, 10, 50, 20, 40};

    // 1. Heap operations
    std::make_heap(nums.begin(), nums.end());
    std::cout << "Max heap top: " << nums.front() << "\n";

    std::sort_heap(nums.begin(), nums.end()); // Now sorted ascending
    std::cout << "Sorted via sort_heap:";
    for (int n : nums) {
        std::cout << " " << n;
    }
    std::cout << "\n";

    // 2. Binary search bounds
    // nums is {10, 20, 30, 40, 50}
    auto lb = std::lower_bound(nums.begin(), nums.end(), 25);
    std::cout << "Lower bound for 25 points to: " << *lb << "\n";

    // 3. Lambda expression with state capture
    int threshold = 25;
    auto countAbove = std::count_if(nums.begin(), nums.end(), [threshold](int val) {
        return val > threshold;
    });
    std::cout << "Elements > 25: " << countAbove << "\n";

    return 0;
}
